# Generated by bentrix-capabilities (rbench) from the Bench table. Do not edit.
# Regenerate: BX_WRITE_SDK=1 on bentrix-shell's test the_r_bench_is_the_tables, which refuses a stale copy.

# What an order came to: ok unless refused; outcome is the venue's word; a refusal's reason is the venue's own
# sentence, kind the word a program branches on, remedy what to change and docs the page. raw is the whole answer.
bx_answer <- function(raw) {
  pick <- function(k) if (!is.null(raw[[k]])) raw[[k]] else raw$last_answer[[k]]
  outcome <- pick("outcome")
  if (!is.character(outcome) || !nzchar(outcome)) outcome <- "sent"
  structure(list(
    ok = outcome != "refused", outcome = outcome, reason = pick("reason"), kind = pick("kind"), remedy = pick("remedy"),
    docs = pick("docs"), ticket = pick("ticket"), order = pick("order"), raw = raw
  ), class = "bx_answer")
}

.bx_ticket <- function(t) if (is.list(t) && !is.null(t$ticket)) t$ticket else t

.bx_quote <- function(page, symbol) {
  for (q in page$items) if (identical(q$symbol, symbol)) return(q)
  NULL
}

.bx_bench_of <- function(client, uri, name = NULL, raise_refusals = FALSE) {
  self <- new.env(parent = emptyenv())
  self$uri <- uri
  self$name <- name
  known <- NULL
  mounted <- FALSE

  # A workbench with no engine mounted (a clone, through the application) is selected - the window shows it, which is
  # how Bentrix mounts one - and waited for, at most a minute.
  mount <- function() {
    if (mounted) return(invisible())
    mounted <<- TRUE
    if (!identical(read_uri(uri)$engine, "none")) return(invisible())
    client$call("select_bench", list(bench = uri))
    for (i in 1:600) {
      if (!identical(read_uri(uri)$engine, "none")) return(invisible())
      Sys.sleep(0.1)
    }
  }

  # Every read through the resource_read tool: a door is anything with call, the connection or the engine's own.
  read_uri <- function(u) client$call("resource_read", list(uri = u))

  # The workbench's markets.
  self$markets <- function() {
    if (is.null(known)) {
      known <<- vapply(read_uri(uri)$markets, function(m) if (is.character(m)) m else m$symbol, "")
    }
    known
  }

  resolve_symbol <- function(given) {
    if (!is.null(given)) return(given)
    ms <- self$markets()
    if (length(ms) == 1) return(ms[[1]])
    .bx_fail("bentrix_error", sprintf("this workbench holds %d markets (%s): name the symbol", length(ms), paste(ms, collapse = ", ")))
  }

  answered <- function(raw) {
    a <- bx_answer(raw)
    if (!a$ok && raise_refusals) {
      stop(structure(class = c("bentrix_refused", "bentrix_error", "error", "condition"), list(message = if (is.null(a$reason)) a$outcome else a$reason, call = NULL, answer = a)))
    }
    a
  }

  read <- function(tail, after = NULL) {
    read_uri(paste0(uri, "/", tail, if (is.null(after)) "" else paste0("?after=", utils::URLencode(after, reserved = TRUE))))
  }

  stream <- function(tail) {
    all <- list()
    after <- NULL
    repeat {
      page <- read(tail, after)
      if (!length(page$items)) return(all)
      all <- c(all, page$items)
      if (!is.character(page$`next`)) return(all)
      after <- page$`next`
    }
  }

  # To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first
  # quote), then a candle of the interval; the closed candle is read back from the window.
  step_ <- function(interval, sym) {
    stood <- read_uri(uri)$cursor_ms
    q <- .bx_quote(read("quotes"), sym)
    if (is.null(q) || is.null(q$at_ms)) client$call("replay_step", list(bench = uri, unit = "tick", n = 1L))
    now <- client$call("replay_step", list(bench = uri, unit = "candle", n = 1L, timeframe = interval))$cursor_ms
    if (is.null(now) || (!is.null(stood) && now == stood)) return(NULL)
    got <- client$call("bars_window", list(bench = uri, symbol = sym, frames = .bx_array(interval), limit = 1L))
    rows <- got$markets[[sym]][[interval]]$rows
    if (!length(rows)) return(NULL)
    r <- rows[[length(rows)]]
    list(time = r[[1]], open = r[[2]], high = r[[3]], low = r[[4]], close = r[[5]], volume = r[[6]])
  }

  # A market buy of lots; sl and tp as prices.
  self$buy <- function(lots, symbol = NULL, sl = NULL, tp = NULL, tag = NULL, group = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["side"]] <- "buy"
    a[["volume"]] <- lots
    a[["symbol"]] <- resolve_symbol(symbol)
    a[["sl"]] <- sl
    a[["tp"]] <- tp
    a[["tag"]] <- tag
    a[["group"]] <- group
    answered(client$call("order_market", a))
  }

  # A market sell of lots; sl and tp as prices.
  self$sell <- function(lots, symbol = NULL, sl = NULL, tp = NULL, tag = NULL, group = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["side"]] <- "sell"
    a[["volume"]] <- lots
    a[["symbol"]] <- resolve_symbol(symbol)
    a[["sl"]] <- sl
    a[["tp"]] <- tp
    a[["tag"]] <- tag
    a[["group"]] <- group
    answered(client$call("order_market", a))
  }

  # A pending order: kind buy_limit, sell_limit, buy_stop, sell_stop, buy_stop_limit or sell_stop_limit.
  self$pending <- function(kind, price, lots, symbol = NULL, sl = NULL, tp = NULL, stop_limit = NULL, expires = NULL, tag = NULL, group = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["kind"]] <- kind
    a[["price"]] <- price
    a[["volume"]] <- lots
    a[["symbol"]] <- resolve_symbol(symbol)
    a[["sl"]] <- sl
    a[["tp"]] <- tp
    a[["stop_limit"]] <- stop_limit
    a[["expires_ms"]] <- expires
    a[["tag"]] <- tag
    a[["group"]] <- group
    answered(client$call("order_pending", a))
  }

  # Only what is named changes: a position's or an order's stop, target, or a pending order's price; 0 removes a level.
  self$modify <- function(ticket, sl = NULL, tp = NULL, price = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    a[["sl"]] <- sl
    a[["tp"]] <- tp
    a[["price"]] <- price
    answered(client$call("order_modify", a))
  }

  # Close a position, all of it or lots of it, or cancel a pending order.
  self$close <- function(ticket, lots = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    a[["volume"]] <- lots
    answered(client$call("order_close", a))
  }

  # Close every position, or one market's, or one group's; nothing open is an answer, not a refusal.
  self$close_all <- function(symbol = NULL, group = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["symbol"]] <- symbol
    a[["group"]] <- group
    answered(client$call("order_close_all", a))
  }

  # Close a position and open the same size the other way, as one act.
  self$reverse <- function(ticket) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    answered(client$call("order_reverse", a))
  }

  # Stop following a position's trailing stop; its stop stays where the trail left it.
  self$untrail <- function(ticket) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    answered(client$call("order_untrail", a))
  }

  # A group of orders under a label: its number, for buy's and close_all's group.
  self$group <- function(label) {
    mount()
    a <- list(bench = self$uri)
    a[["label"]] <- label
    client$call("group_open", a)[["group"]]
  }

  # A trailing stop at points from the price, the venue's own.
  self$trail <- function(ticket, points) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    a[["points"]] <- points
    answered(client$call("order_trail", a))
  }

  # Cancel a pending order; the same act as close on an order's ticket.
  self$cancel <- function(ticket) {
    mount()
    a <- list(bench = self$uri)
    a[["ticket"]] <- .bx_ticket(ticket)
    answered(client$call("order_close", a))
  }

  # What an order would cost and hold - its margin, its money a point, its price - sending nothing.
  self$preview <- function(side, lots, symbol = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["side"]] <- side
    a[["volume"]] <- lots
    a[["symbol"]] <- resolve_symbol(symbol)
    client$call("order_preview", a)
  }

  # What the book holds by market: lots net and gross, each market's notional, the account's ratios.
  self$exposure <- function() {
    mount()
    read("exposure")
  }

  # The last closed candles of interval, oldest first.
  self$bars <- function(interval = "M1", limit = 100L, symbol = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["timeframe"]] <- interval
    a[["limit"]] <- limit
    a[["symbol"]] <- resolve_symbol(symbol)
    page <- client$call("bars_get", a)
    rows <- page$bars
    if (isTRUE(page$last_forming) && length(rows)) rows[-length(rows)] else rows
  }

  # The book: positions, orders and the account.
  self$book <- function() {
    mount()
    read("book")
  }

  # The open positions.
  self$positions <- function() {
    mount()
    read("book")$positions
  }

  # The resting orders.
  self$orders <- function() {
    mount()
    read("book")$orders
  }

  # The account: balance, equity, margin, free margin, currency.
  self$account <- function() {
    mount()
    read("account")
  }

  # Every deal, oldest first.
  self$deals <- function() {
    mount()
    stream("deals")
  }

  # The venue's event log, oldest first.
  self$events <- function() {
    mount()
    stream("events")
  }

  # Every order the workbench was sent, oldest first: what it became and when.
  self$order_history <- function() {
    mount()
    stream("orders")
  }

  # The market's bid and ask at the clock, or none.
  self$quote <- function(symbol = NULL) {
    mount()
    .bx_quote(read("quotes"), resolve_symbol(symbol))
  }

  # A market's facts as numbers: digits, point, contract, volumes, stops level, swaps, sessions.
  self$spec <- function(symbol = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["symbol"]] <- resolve_symbol(symbol)
    client$call("symbol_info", a)
  }

  # Several timeframes at once, closed candles only, each with its forming candle.
  self$window <- function(frames, limit = 100L, symbol = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["include_forming"]] <- TRUE
    a[["frames"]] <- .bx_array(frames)
    a[["limit"]] <- limit
    a[["symbol"]] <- resolve_symbol(symbol)
    client$call("bars_window", a)
  }

  # Its conditions and their digest.
  self$manifest <- function() {
    mount()
    a <- list(bench = self$uri)
    client$call("bench_manifest", a)
  }

  # To the next close of interval: the closed candle and where the clock stands, or none where it moves no further.
  self$step <- function(interval = "M1", symbol = NULL) {
    mount()
    step_(interval, resolve_symbol(symbol))
  }

  # Forward to a moment, at most the days' last; where the clock stands.
  self$advance <- function(to) {
    mount()
    a <- list(bench = self$uri)
    a[["stop_at_end"]] <- TRUE
    a[["to_ms"]] <- to
    client$call("replay_seek", a)[["cursor_ms"]]
  }

  # Back to a moment; refused with its door when that would undo a deal, unless undo_deals.
  self$rewind <- function(to, undo_deals = FALSE) {
    mount()
    a <- list(bench = self$uri)
    a[["to_ms"]] <- to
    a[["undo_deals"]] <- undo_deals
    client$call("replay_seek", a)
  }

  # A checkpoint to a file.
  self$save <- function(name) {
    mount()
    a <- list(bench = self$uri)
    a[["path"]] <- name
    client$call("checkpoint_save", a)
  }

  # A checkpoint back, refused under other conditions.
  self$load <- function(name) {
    mount()
    a <- list(bench = self$uri)
    a[["path"]] <- name
    client$call("checkpoint_load", a)
  }

  # A workbench alike, in this one's state by default.
  self$clone <- function(state = TRUE, name = NULL) {
    mount()
    a <- list(bench = self$uri)
    a[["state"]] <- state
    a[["name"]] <- name
    made <- client$call("bench_clone", a)
    .bx_bench_of(client, made$uri, made$name, raise_refusals)
  }

  # Keep where it stands, to watch on the chart: a clone in its state, under a name.
  self$keep <- function(name) {
    mount()
    a <- list(bench = self$uri)
    a[["state"]] <- TRUE
    a[["name"]] <- name
    made <- client$call("bench_clone", a)
    .bx_bench_of(client, made$uri, made$name, raise_refusals)
  }

  self
}

# A workbench: the one named (its name or its address), else the selected one, else the first.
bx_bench <- function(client, name = NULL, raise_refusals = FALSE) {
  state <- client$call("get_state")
  every <- list()
  # A laboratory's workbenches, then a REAL account's (paper among them).
  for (area in c("laboratories", "accounts")) for (home in state[[area]]) every <- c(every, home$benches)
  pick <- function(b) .bx_bench_of(client, b$uri, b$name, raise_refusals)
  if (!is.null(name)) {
    for (b in every) if (identical(b$uri, name) || identical(b$name, name)) return(pick(b))
    names <- vapply(every, function(b) paste0("'", b$name, "'"), "")
    .bx_fail("bentrix_error", sprintf("no workbench is named '%s'; there are %s", name, if (length(names)) paste(names, collapse = ", ") else "none"))
  }
  if (!length(every)) .bx_fail("bentrix_error", "the workspace holds no laboratory workbench")
  for (b in every) if (!is.null(state$selected) && identical(b$uri, state$selected)) return(pick(b))
  pick(every[[1]])
}
